<script setup lang="ts">
import {ref,onMounted} from 'vue';
import {catalogApi,feedbackApi} from '@/api';
import ItemCard from '@/components/ItemCard.vue';
const about=[{title:'Трассы',text:'Подготовленные трассы разного уровня сложности',image:'/images/about-slopes.jpg'},{title:'Подъёмники',text:'Современные подъёмники для быстрого доступа к склонам',image:'/images/about-lifts.jpg'},{title:'Комфорт',text:'Всё необходимое для комфортного отдыха',image:'/images/about-comfort.jpg'}];
const selected=ref(0),lessons=ref<any[]>([]),equipment=ref<any[]>([]),instructors=ref<any[]>([]),loading=ref(true),error=ref('');
const name=ref(''),contact=ref(''),message=ref(''),feedbackStatus=ref(''),sending=ref(false);
onMounted(async()=>{try{const result=await Promise.allSettled([catalogApi.lessons(),catalogApi.equipment(),catalogApi.instructors()]);if(result[0].status==='fulfilled')lessons.value=result[0].value;if(result[1].status==='fulfilled')equipment.value=result[1].value;if(result[2].status==='fulfilled')instructors.value=result[2].value;if(result.some(r=>r.status==='rejected'))error.value='Не удалось загрузить';}finally{loading.value=false}});
async function send(){feedbackStatus.value='';if(!name.value.trim()||contact.value.trim().length<5||message.value.trim().length<5){feedbackStatus.value='Заполни имя, контакт и сообщение (не менее 5 символов).';return;}sending.value=true;try{await feedbackApi.send({name:name.value,email:contact.value,message:message.value});feedbackStatus.value='Спасибо! Мы свяжемся с тобой.';name.value='';contact.value='';message.value='';}catch{feedbackStatus.value='Не удалось загрузить'}finally{sending.value=false}}
</script>
<template>
<section class="container"><div class="hero"><svg class="hero__mountains" viewBox="0 0 1000 300" preserveAspectRatio="none" aria-hidden="true"><path d="M0 220 L180 120 L380 230 L520 80 L700 210 L780 170 L1000 260 V300 H0Z" fill="currentColor" opacity=".25"/><path d="M0 260 L250 180 L450 250 L650 150 L820 230 L1000 200 V300 H0Z" fill="currentColor" opacity=".35"/></svg><div class="hero__content"><h1 class="hero__title">Открой для себя мир горных приключений!</h1><p class="hero__text">Проведи незабываемое время на склонах, освой новые навыки и насладись красотой гор</p><RouterLink to="/lessons" class="btn btn--light">Выбрать занятие</RouterLink></div></div></section>
<section class="container section" id="lessons"><div class="popular"><div class="popular__intro"><h2 class="popular__title">Найди своё идеальное занятие</h2><p>От первых шагов на лыжах до уверенного спуска по сложным трассам — у нас найдётся занятие для каждого</p></div><ItemCard v-for="item in lessons.slice(0,3)" :key="item.id" :item="item" kind="lessons"/><div v-if="!lessons.length" class="card panel">{{loading?'Загружаем занятия...':'Не удалось загрузить'}}</div><div class="popular__more"><h3>Больше занятий в каталоге</h3><p>Выбирай направление и уровень подготовки</p><RouterLink to="/lessons" class="btn btn--light btn--block">Все занятия</RouterLink></div></div></section>
<section class="container section" id="rental"><div class="section-head"><div><h2 class="h2">Всё для комфортного катания</h2><p class="lead">Не нужно покупать собственное снаряжение. Выбирай подходящее оборудование</p></div></div><div v-if="equipment.length" class="grid grid--3"><ItemCard v-for="item in equipment.slice(0,3)" :key="item.id" :item="item" kind="equipment"/></div><div v-else class="card panel">{{loading?'Загружаем оборудование...':'Не удалось загрузить'}}</div></section>
<section class="container section" id="instructors"><div class="section-head"><div><h2 class="h2">Учись у профессионалов</h2><p class="lead">Наши инструкторы помогут освоить технику катания и почувствовать уверенность на склоне</p></div></div><div v-if="instructors.length" class="grid grid--3"><ItemCard v-for="item in instructors" :key="item.id" :item="item" kind="instructors"/></div><div v-else class="card panel">{{loading?'Загружаем инструкторов...':'Не удалось загрузить'}}</div></section>
<section class="container section" id="about"><div class="about"><div class="about__left"><h2 class="about__title">Твой отдых начинается в горах</h2><p class="about__lead">Наш горнолыжный курорт — место, где встречаются активный отдых и яркие впечатления</p><ol class="about__list"><li v-for="(a,i) in about" :key="a.title"><button class="about__item" :class="{'about__item--active':selected===i}" @click="selected=i"><span class="about__num">{{String(i+1).padStart(2,'0')}}</span><span><span class="about__item-title">{{a.title}}</span><span class="about__item-text">{{a.text}}</span></span></button></li></ol></div><div class="about__right"><img class="about__photo photo" :src="about[selected].image" :alt="about[selected].title"/></div></div></section>
<section class="container section" id="contacts"><div class="section-head"><div><h2 class="h2">Мы всегда на связи</h2><p class="lead">Остались вопросы? Свяжись с нами — поможем подобрать занятие</p></div></div><div class="grid grid--2"><div class="card contacts-card"><div class="contacts-card__label">Адрес</div><div class="contacts-card__value">Красная Поляна, ул. Горная, 15</div><div class="contacts-card__label">Телефон</div><div class="contacts-card__value">+7 (800) 555-35-35</div><div class="contacts-card__label">Email</div><a class="contacts-card__value" href="mailto:info@montis.ru">info@montis.ru</a><img class="contacts-card__map photo" src="/images/about-slopes.jpg" alt="Вид на курорт"/></div><form class="card form" @submit.prevent="send"><h3 class="h3">Форма обратной связи</h3><p v-if="feedbackStatus" class="alert alert--info">{{feedbackStatus}}</p><input v-model="name" class="input" placeholder="Имя" required/><input v-model="contact" class="input" placeholder="Телефон или email" required/><textarea v-model="message" class="input input--area" placeholder="Сообщение" rows="4" required/><button class="btn btn--primary btn--block" :disabled="sending">{{sending?'Отправка...':'Отправить'}}</button></form></div></section>
</template>
